using System;using System.Collections.Generic;using System.Drawing;using System.Reflection;using System.Windows.Forms;
class MenuUiChecks{[STAThread]static void Main(){int saves=0;var shelf=new List<int>{0,1,2,3};using(var form=new Form())using(var view=new RecipeMenuView(".",shelf,()=>saves++)){view.Dock=DockStyle.Fill;form.Controls.Add(view);form.Show();foreach(var size in new[]{new Size(800,600),new Size(1280,780),new Size(1920,1080)}){form.ClientSize=size;Application.DoEvents();using(var bmp=new Bitmap(size.Width,size.Height)){view.DrawToBitmap(bmp,view.ClientRectangle);bmp.Save(System.IO.Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"menu-"+size.Width+".png"));}}var field=typeof(RecipeMenuView).GetField("add",BindingFlags.NonPublic|BindingFlags.Instance);var rect=(Rectangle)field.GetValue(view);var click=typeof(RecipeMenuView).GetMethod("OnMouseDown",BindingFlags.NonPublic|BindingFlags.Instance);click.Invoke(view,new object[]{new MouseEventArgs(MouseButtons.Left,1,rect.X+10,rect.Y+10,0)});if(shelf.Count!=3||saves!=1)throw new Exception("remove failed");click.Invoke(view,new object[]{new MouseEventArgs(MouseButtons.Left,1,rect.X+10,rect.Y+10,0)});if(shelf.Count!=4||saves!=2)throw new Exception("add failed");if(FoodCatalog.Names.Length!=24||FoodCatalog.Descriptions.Length!=24)throw new Exception("catalog mismatch");Console.WriteLine("PASS: 3 sizes, add/remove, persistence callback, 24 ingredients");}}}
